  VALUES 
    (555::BIGINT, 'Ella es la mejor profe que pude haber tenido para lab, te ayuda siempre en todo lo que pueda es atenta contigo y siempre intenta ayudarte a que aprendas las cosas y califica suave y es muy comida la mejor un 10 la profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'b2663b20de23ec7479c18ccccbab5b9279d423f7bc6d316a0fc1594afa6b3b0d'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Es probablemente la mejor profesora que he tenido en mi vida, quiere realmente que todos aprendan, dedica mucho tiempo a enseñar, practicar y hacer que sea dinámico todo, muy divertida, en los exámenes es muy atenta a quien necesita ayuda y quien ocupa respuestas, recomendadísima'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-04-04T00:00:00+00:00'::TIMESTAMPTZ, 'c09814e387db6370caf41f11400709adf08cbf2c7f0b31ff303de751b178bd18'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'de verdad que no tengo palabras para expresar lo excelente que es la profe jacque dando clases, de verdad que le apasiona y se refleja en como brinda la materia, tqm profe, los quizes tienen cierto grado de dificultad pero lo necesario, no dude en matricular con ella!!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'b6df1b0ecf971e80b597c536976a9ae4b7db0a4119433fd75d1130f7e15718e5'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'SIEMPRE ODIE LA QUIMICA, PERO CUANDO LLEVE EL CURSO CON LA PROFE HIZO QUE PARA MI ESE CURSO FUERA UNO DE LOS MAS BONITOS, EN VERDAD ES UN SOL DE PERSONA. LLEVE CON ELLA SIN DUDA, AMA LO QUE HACE Y REALMENTE AMA ENSEÑAR.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'e13e7e2e791625a7b6576ca61008d51bf51f2e02f1ddc375599296107ae90f4a'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'En mi opinión es la mejor profesora para Laboratorio de Orgánica, debería ella ser una de las profes que den teoría. Es excelente, uno sale aprendido, y realmente las clases son hermosas. Se debe de estudiar, pero el conocimiento que ella imparte combina lo práctico y lo teórico'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'c48f2253f03c84eb8228dcbbd5f55b62fa682d47e63549a2aee0292698ea74b6'::TEXT, ARRAY[2738]::BIGINT[]),
    (555::BIGINT, 'Súper recomendada si vuelve a dar el lab, era la primera vez que lo estaba dando y dentro de los enredos que hace el coordinador de orga, ella sabía adaptar bien las clases, los quices son sobre analizar casos y ponen a pensar al estudiante en una situación real, fáciles.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'ab3562fa20770865162c513b2ffa6a817ecbdc5e8977b7ab06116d71682866e8'::TEXT, ARRAY[2738]::BIGINT[]),
    (555::BIGINT, 'Muy buena Profe, si puede matricule con ella, realice los quices de buena manera y así le ayuda bastante para la nota, al ser coordinadora ayuda bastante y da repasos. No hay otra mejor opción que ella .'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '339c5d03df4012242226bf316dba8a61c267d629d45712e3dfa8e1b69df5fcd3'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'La mejor profe para química II, la asistencia es muy importante. Explica demasiado bien y está interesada porque todos aprendan'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2024-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'd73ee91e9e5a62057373f4320eaa40853e7db189c1b8a6c5f3b5205baf3b6809'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Califica un poco duro, pero te da TODAS las herramientas para desempeñarte bien, tiene un interés auténtico por que el estudiante entienda, una profe que me cambió la perspectiva, matriculen con ella sin dudas, es MUY justa (para bien o para mal)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-03-10T00:00:00+00:00'::TIMESTAMPTZ, '3eb72de63c0b2725f26a2d8410078b61149d0ce490f766f172ae606768128d08'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'De las mejores, entreguen todo asi sea extra, ayuda muchisimo para los exmenes'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-26T00:00:00+00:00'::TIMESTAMPTZ, '64c38769e7352ad6a30c96872915e4cffe398b5a74f6009ba0c4b5235ccfed12'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Quizás no va a parecer la más amigable en un inicio, pero de verdad se preocupa demasiado por sus estudiantes. Eso incluye muchos quices y rudos, pero son la mejor preparación para el examen. Explica la materia mil y un veces de distintas maneras y tiene mucho material de apoyo. La mejor para QBII'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-12T00:00:00+00:00'::TIMESTAMPTZ, '94395af4004dae163363a2faf25fbe927b20c22aa79a41d0bc02571fd0081c4b'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'La profe explica demasiado bien y hace que el curso no se sienta tan pesado como realmente es, los quices sí son duros, pero ella deja bastantes extra para recompensar. Matricule a ojos cerrados con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '91c9dd7aa35c3f93a07ecf3fbed75d6b57e9192005e292bce70ef89e907b4ce3'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Excelente profesora. Nos brinda mucho material para estudiar como prácticas, apuntes y videos. Como fue/es coordinadora, los quices y práctica en clase ayudó muchísimo ya que se parecía mucho a la manera de evaluar en los exámenes. Hace quices/tareas extra para subir la nota. Súper recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'bce4725053a2aa316e6eba824d96a4bb95c163a6bad48e578f24c0ed3c7734e9'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Explica la materia infinidad de veces con distintas metodologías. Las clases no se hacen pesadas. Es coordinadora de cátedra, si lleva con ella va a conocer más el estilo del examen. Los quices son duros y con justifique, además de hacer muchos ejemplos en clase para prepararnos. Recomendada!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'a5164810521b5ae8e60776a47945b3ef62199e7e109deb7702bb222598cb9793'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Excelente profe. Los exámenes cortos tienen cierta dificultad y muchos ejercicios con una parte de justificación de su respuesta. A la profe le interesa más que los estudiantes entiendan bien y no se memoricen cosas. Excelentes clases con práctica.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '6c4ea51fb4d729afb3abd3feef246b4d3e8f10b300f2ead066a59409557d826a'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Excelente profesora! Si pudiera matricular otro curso con ella lo haría sin pensarlo. Se nota que le gusta lo que hace y explica de las formas mas creativas para que aprendas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'aba85e930abd5395ea98c200a493d867fda7d215763cf9ecfc38abf42bca94f7'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Excelente profe y persona, súper recomendada'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7d2361349fe4e311bba2fda5fad05b4a0872272417a20d0b9d15096d36087b50'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Clases cortas, quices extras y mucha práctica en base a examenes en clases. Excelente profe y persona, cae super bién y se nota que le encanta la química y lo que hace. Excelente opción para el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8639ffcc8c13cb0e27980268cf33374dc1dcd9b7610f2b49c122c872bd7cadf5'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Excelente profesora, explica ejercicios y hcae quices en la forma en que se evalúa la materia en los exámenes, hace actividades diferentes y no hace las clases muy largas, además tiene apuntes con la materia resumida y ejercicios explicados.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd678168d1d04526327839986b4c29e75f7fadf67df42b9f7ae8c2386351d7fc7'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'a5864a11e8470750ce24805810fe01f6703f63a8a7e921232bf84076cea2c037'::TEXT, ARRAY[573]::BIGINT[]),
    (555::BIGINT, 'Excelente profesora, da buena retroalimentación y tiene apuntes muy bonitos y claros.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '76e842f0ebb81508a5e0275da873fdaeacd2751853782d4f60a5832346a15411'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Muy buena profe, se preocupa por el estudiante y aveces hace quiz extra con tal de ayudarlo a pasar. quiz dificiles pero vale la pena'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'cca19870b0379be38b19d7520271f06fd1d2e3cff850db75acfb9deeba377232'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es una profe muy cómica y sus clases son muy dinámicas, explica lo mas bien la materia y brinda muchísimo apoyo a los estudiantes con apuntes y videos, sus quices son muy duros pero vale la pena llevar con ella, uno sale bien preparado'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'de63ac080442e2cbbc6b3cd8ac33d52f8c466ed4fe20ea03ed39de1a11d02a22'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'La mejor profe que he tenido en toda mi vida. Explica super bien, ofrece más ayuda de la que ya da, sus apuntes son excelentes... todo es demasiado bueno. OJO: véase GOT/HOTD/STAR WARS a la profe le encanta y a veces pone puntos extra sobre esos temas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, '6e200a1e5241e0daf85bf78f20b4104f47b067a471fbacd8d78528354a44c4fb'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Buenísima profe, se preocupa mucho por dar las clases y brinda muchisimo apoyo y material, por la evauaciíon del curso si es ideal llevar la materia al día para pasarlo, pero la profe ayuda muchísimo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2022-11-21T00:00:00+00:00'::TIMESTAMPTZ, '7471cacf07a639660b9608533a3d25ed29f87ff3f4e61ad1c19b196060e60253'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Súper recomendada, solo sepa que los quices son bastantes dificiles(algunos se pueden hacer en grupo o pareja y pueden ser virtuales), pero nos prepara bien para los exámenes. Explica muy bien y es muy buena nota. Si puede, de fijo meta con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'f3ec67a54df4cfc0059f65d31b376c7b5b226172980b00659931e32372050f59'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Excelente profesora, tiene el TecDigital muy ordenado y super buena, maneja los temas de una manera muy clara, lo único es que en las presentaciones a veces las sobrecarga de información.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '6a83732849115858782b6b83ed5f6e4b2e9165f6ad896ea0045d33bb77ecba33'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Las clases son super claras, se preocupa que el estudiante entienda. Hace como mínimo 3 quices extra, por lo que ayuda mucho a subir la nota. Los exámenes son fáciles, deja bastante práctica que sirve mucho, con que la haga va super preparado para el examen. También tiene el TecDigital superordenado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '55816d79f5bf8dcd4224ed7f5a514499d09529cae6709c133d663c45da307b30'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'De las mejores profesores que tiene la universidad, explica super bien, da mucho material de apoyo, se interesa porque el estudiante aprenda. Hace muchos quices pero ayuda a que no peguen tanto en el promedio. Super recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '2d055dde84c97c2e2126f5656d09a6242eec59a472cb55206afb81c368909657'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Súper simpática, ordenada y le importa el bienestar de sus estudiantes. Explica súper bien, y con solo poner atención y estar al día se aprende muchísimo. Da mucho apoyo con sus apuntes, prácticas y trabajos extra. Recomendadísima.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'f141b29f79eaffb7485d194e128ee3c0f1f86118ea9c0e41599f0a368a0a3816'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Excelente profe, las clases no duran más de una hora (virtual). Son un poco aburridas. Pero es una profe que se preocupa por los estudiantes y siempre hace extras que lo ayudan bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd801b21d09b50a7d2df8dc9073e9b262058b75aa0d41a9625378f23fa1088666'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'La profesora es muy buena gente y se preocupa bastante por sus estudiantes, en virtual da normalmente una clase asincrónica y otra sincrónica, es importante llevar la materia al día ya que deja como tarea hacer resumenes que al final sirven para estudiar, los quices no son muy dificiles.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-01T00:00:00+00:00'::TIMESTAMPTZ, 'b47a3a6ebdad2f20403018f966e1135cf39f5a7f8b94df2d2f3a84c46bd1754e'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es una profe muy buena , ayuda mucho , da repásanos los sábados antes del examen o un día que se pongan de acuerdo y explica todo para que se entienda bien Siempre se comunica y busca la mejor manera para cada asignación con el grupo , se nota que quiere ayudar y explicar de la mejor manera !'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '50e781047c375bc7a4510644f25c638de52fea099f5ac62efc65f6280424d2ae'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Explica muy bien la materia, aunque espera que uno preste atención en clase y luego guarde o copie sus apuntes, que son muy completos solo que a veces no los sube a tiempo. Sus quices son difíciles pero preparan relativamente bien para los exámenes y sus repasos previos a exámenes son excelentes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '9bdd26cfbaa991bd7129ea7c69bde3a6c39461d2d2d8e14e5dc3105d32fefb27'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Muy buena profesora, se ve que le apasiona enseñar, hace quizzes díficiles en comparación al examen, pero es cuestión de estudiar. Deja muchos ejemplos y material de apoyo.La mejor opción para química más que recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'c164b34e06772848d33434615f9c233e05975c183d3780330c78be1411c49a6b'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Excelente profesora, explica bastante claro. Hace quices, un poco difíciles comparados al examen pero nada del otro mundo. También se hacen resúmenes que califica como quices, lo cual es una super ayuda. No dude en matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'ab7f65262433817d285ddb5dc56f8493946faa71b28e50acf949e3d93f42989c'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Excelente como profesora, se nota que le gusta dar la clase. Los apuntes que hace son muy desordenados pero si prestó atención en la clase se entienden. Probablemente la mejor para este curso y todos los que da'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'cd55346bbf3fda7486a73bdac2309a6abce8b8991819914d9dedde882fb92e54'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Una profe excelente, que se le notan las ganas de enseñar aunque a veces las diapositivas que presenta son un poco confusas, pero nada del otro mundo. Siempre es muy abierta a las dudas y a la hora de resolverlas muestra amabilidad total. Dispuso de distintas opciones para sustituir quices... 10/10'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'f94239721e7e79f778c9a81c8ab2f5a6fd90c5bd9eb991a0521c31be5d88f8b6'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'La profe sabe bastante bien la materia, sin embargo, a veces se enreda explicando entonces hay que estar muy atento. Los quices tienen un poco de dificultad, pero es todo lo que ella explica en clase, solo estudiar bien. Siempre está atenta a ayudar. Recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd501635c5c121597e70b6172abf123c2d139f93af86fcdb7fba51dc9cc741ca1'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'La profe es excelente, nos hizo un trabajo con puntos extra que ayudó a que muchos llegarán a repo o pasarán. Aprovecha mucho la tecnologia y los simuladores o calculadoras de internet, es super atenta ante las dudas y nos dió repasos para todos los examenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '14699738d959c28c6a19aaab0fc0acfa1d508759b05dabe947c94ab7216da9b4'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Es muy amorosa y siempre se preocupa porque uno entienda. Explica super bien y en virtual utiliza materiales excelentes para ir explicando. Da mucho material de apoyo. Siempre atiende dudas. Si puede meterlo con ella hagalo de una.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6d874613a8f0999d64299af3901733dfc0b5e63b951907be3769a2da190250a9'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'La profe es súper buena. Explica clarísimo, hace ejemplos en clase y hace resúmenes y prácticas muy buenas. Los quices son sencillos si uno estudia y lleva la materia al día. Responde súper bien aunque sean preguntas extremadamente tontas. Para química II, la recomiendo totalmente a ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '91f7ba1c3cb94daf04d2ea3007974ebc143995001964151797edd4bd8e94e751'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Virtual, fue un poco dinámico, la profe aveces se embota cuando explica y más bien enreda, pero en general es bastante buena, explica bien, es muy accesible y aclara las dudas que uno tenga. Los quiz son nivel intermedio, aveces los hace un poco rudos aveces fáciles.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-18T00:00:00+00:00'::TIMESTAMPTZ, '6597ca8fc25b0b8e13b336a8c72ca619bc47c415f65fabea9501392aaf2a06d6'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Explica muy bien y le importa que los estudiantes entiendan. Hace muchos ejemplos y deja prácticas super buenas (con hacerlas saca 100 en el examen). Pocos trabajos y sencillos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-02-17T00:00:00+00:00'::TIMESTAMPTZ, 'ad3d79818cc9151ce7c3ddbdfd676df5ff88f12061c8a6738b92ca9ce65f55e1'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Muy buena profesora. Explica muy claro los temas, deja muchas practicas para mejorar, sube videos a youtube de como se resuelven los problema para el examen y es muy comprensible.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-15T00:00:00+00:00'::TIMESTAMPTZ, '4748eb18d72bec951e2cee1f35b651af7a3ee878a1c1442cbda9e86ad7d8a6a1'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'La profe es muy carga, mas las clases aveces son un poco largas, sabe mucho del tema, no tiene calculadora xd pero explica bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '422b35c22996cf2b0eb112ce303af0722ab5a01e8ffeed921caf852a3c96fa86'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Ella explica muy bien, es impresionante la disposición que tiene para responder dudas y brindar apoyo. Le encanta que le pregunten. Por lo general, maneja los apuntes y las grabaciones de las clases muy bien. Se aprende bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'a5e6bb777c1ab202305f8593151e0851b161da030518f51e3a7e0c0422d8883d'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Ella es súper buena en virtualidad, brinda mucho material y ayuda bastante'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'e9d3f6d854b1ebbaf020086b5c10c9bd983dc86153072f0ec6937f8763520048'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Se olvida de subir los videos de la clase y si falta a una se atrasa en todo el curso, pero en general es muy buena profesora y tomaría su clase de vuelta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '0c0d80b089b966881be6ed05407738f072bd1500a4489672f311e950497eb30c'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es muy buena profe y super ordenada. Explica muy bien y suele responder casi que al instante. Ella hace apuntes para explicar la clase y luego los pasa. Super recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '713c0e22d2d2c68b91e2ea536b195365f196cfffc7ddd2507c8f947119b41081'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Una de las mejores profes que he tenido, explica demasiado bien y es muy paciente. Super recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '7faeee9c58400ca87089dadd5898ebcb925c6ab9a88abd170aafe66e00f06023'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Excelente profe, le pone mucho esfuerzo a las clases y explica muy bien. A veces los quices son un poco difíciles pero da puntos extra.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '74ec583ed1dbac95e2191c6c4087de9bd93e77afe1a57bd1aa9ba5462a3fe4d1'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Una profesora excelente, se acomodo súper bien a la virtualidad. Matricule con ella sin miedo, no se va a arrepentir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'de82f7ad0d8839cc93c542c1ea683df94a64296435cc132bb81d11a3c4be9c64'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Es divina!! Una excelente profesora y se acomodó muy bien a las clases virtuales'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'a5d01dcc1279f99b16ef1f64f06e92cfa66dd67cd0878e45adfef8138844c970'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Explica súper bien, las clases son entretenidas y hace bastantes ejercicios para que el tema quede claro, explica las veces que sea necesario para que usted entienda y es muuuy amable. Los quices son fáciles y siempre busca lo mejor para el/la estudiante. Recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '7b2631702ce9c90ec98c289f083812c5d5cfc8382116c8e875036d510ce7b4b7'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '8cb9284fdd107052c48aad90c2156eecf5cf62ec4cfede61d70a929a53f4385a'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, '20/10 como profesora, tanto presencial como virtual. Desde el inicio del curso tiene todo súper organizado, las presentaciones de todo el curso y sus respectivas prácticas por semana, es importante llevar la materia al día pues hace quices continuamente. Es importante la participación en clase!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'b73c56fae77d3d1d8b1fc1b80d8207e0c7d761e3427874aab5637dc2d64b1de4'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Yo prácticamente pasé la materia viendo las clases y sacando bastantes apuntes. Se nota que sabe demasiado de la materia y si es de ayudar lo hace. La participación en las clases es muy importante entonces aunque no sepa nada active el micro y diga algo. Tiene que ir con la materia al día.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '22614ac30bf8df45a8a5e44738f863ab0ad35d2a10b1d240e0929e69a661c5b3'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es una excelente profe, ayuda bastante con extras, explica muy bien y esta muy atenta a contestar dudas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '13c341910afc4664908141e33f4e48d4b6265723ea9cfd6bd244cc195b8d2588'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Virtual ayuda mucho, hace grupos en WA y siempre está al pendiente de dudas. Y es buena nota a la hora de ayudar a la gente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '21aaa35c303d5933c6b1498db33673a1b3be9edaa1b5a462bf7b74544ddd17d4'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Es muy buena profe, ayuda mucho y es amable. Virtual es un 20/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '4bf41ec4508d41514038b1a5e984267bd913d8b1c6bdf1a28cf7be5f83f7c90c'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es una buena profe y ayuda a los que se esfuerzan.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '20d457fdb160a4e025b501f0c1b479ca03889899456e0799034a6ca48ba2a424'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, '687129e3e38e23bc9366b6cf1a06b9dc919874019e11c523ebe9c7f7529b1c96'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Es la mejor profesora de la escuela de química, si puede matricule con ella no se arrepentirá. En modalidad virtual sigue siendo igual de buena, matricule con ella, no otro profe tan bueno como ella para este curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '954199fc9c1ffdeae5576ca44de85508b3a2a0d0b5978f7d75ef97cc4e60f548'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Simplemente la mejor profe de Química, ayuda un montón cuando explica y surgen dudas, hace muchos quices que al final ayudan un montón. En modalidad virtual sigue siendo sumamente buena para dar la clase, además que es muy pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'c47b645df1222d3ad8c00da31299f81582383589f562c889fbec997e39adc304'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Jesús Cristo en persona. Si no pasa con ella está en la piedra su alma ????'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'd6c371280127fb5f632446a439c32dc333020040812f7ec1bf4b237b7159a71f'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'La mejor profesora de la escuela de química para modalidad virtual, creo que es la profesora que mejor se adaptó a las clases virtuales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'a758967570ec8eaf5af7938636672954a657d32fe6f48bb4b7eb401b23990175'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Me dio clases solo 5 semanas pero en ese tiempo demostró ser demasiado buena profe. Explica todo muy claro y fácil, y si uno ocupa que se devuelva ella lo hace con todo gusto. Además es toda linda persona, y usa presentaciones muy ordenadas. 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-08T00:00:00+00:00'::TIMESTAMPTZ, '9d7a6ed85e63d53dd0acb90f248eedf78436c21c5b0adcb59b3817265bcf87e4'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Es muy buena explicando. Usa presentaciones muy coloridas y lindas. Se entusiasma mucho al explicar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '6e532b84577a196d68277c99adb209911b7df9b4a5aede0ee26286be9912f61d'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Es demasiado linda y hace la clase super fácil y llevable'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ea83a04809f5102f255faeb0e2993c9160a48dab00d9ced48184ec939013bdd8'::TEXT, ARRAY[1857]::BIGINT[]),
    (555::BIGINT, 'Súper buena profe, se nota el entusiasmo que tiene para dar clases, es muy amorosa y cariñosa, le encanta que los estudiantes le pregunten y siempre hace las clases muy amenas con charlas completamente fuera del tema. A pesar de que el curso es pesado ella busca cómo pasar a todos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, '251de6fc3b71b7bba583d4c898f8d3c6bfd545c6a02de3e521523f1e84cd1200'::TEXT, ARRAY[1857]::BIGINT[]),
    (555::BIGINT, 'es buena profe, siempre trata de que todos entiendan pero muy pocas veces lo logra. se enreda mucho cuando habla y es muy firme conforme a la posicion de ella en todos los temas. los trabajos suelen ser faciles pero los examenes son largos y un poco mas dificiles.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a27fa98bb5cfe4c2de9e24818dd9920992c69595966ea5182eeedcab09ffa56f'::TEXT, ARRAY[1857]::BIGINT[]),
    (555::BIGINT, 'Explica y presenta la materia con claridad. Los quices y práticas ayudan mucho para los exámenes. Excelente profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a0fe0b613cad0f33a90ece4d1208b30b40e9a4187eb17a9b09a94779734ebb82'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Es de las mejores profesoras del TEC, interesante, apasionada, deja prácticas de nivel superior a examen que luego son una bendición y ella siempre está dispuesta a ayudar. Lo malo es que para este IIS 2019 de fijo se va un tiempo porque va a tener un bebé.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b3fbfba68b816a9c534602f02c3ab1c0951c3bcf39abe8161ef047d29b2469d1'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Semi-virtual, el curso es fácil y ella explica increíble, solo que hay que entregar resúmenes y tareas todas las semana (Bastante flexible con eso) pero si hace que el curso se vuelva demasiado pesado, seguro se va II Sem 2019 un tiempo porque está embarazada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'f6b64adaf3dc9c729de22fb9106c457eaa940424e2a17de5191ef423f4b733ef'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Una Diosa! Explica muy bien y es súper pura vida. Deja prácticas con respuesta y con un nivel muy superior al examen. Lo único es que hace quices enormes(para la casa) o tareas casi todas las semanas. Ayuda demasiado y de verdad que es de las mejores profes del TEC que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '3370d9595dcfdd24a793f9c85f9099e56248bd52966a4493fbfcaaa7d83d037a'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Buena profe, en ocasiones recarga mucho las clases, pero siempre está dispuesta a repetir cuando no queda clara la materia. Quices fáciles.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '77da26e90a3595cbae4be3fcebdab723c40d1fca2fff8d7b988cdae26145dbd4'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es la mejor profesora con la que he llevado clases, sus lecciones son muy interesantes, es demasiado clara y ayuda mucho cuando uno no entiende (a veces puede ser un poco abrumador), no dude en matricular con ella'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6a789c4a9fa0ad33ed21b4e887216a180bc66cc965c89f52b700d40b4ff58b6f'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es muy buena profe, muy graciosa y hace la clase muy amena. Los quices son enormes. A veces como que le hacía falta dar una explicación más coloquial, pero de igual manera explica muy bien. Recomendada.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'e02228c3bdd1e15d0fb9689c3b8ffae852c0a5d426a4f0049be50ade1f48ba82'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Muy buena profe, las clases no son tan aburridas gracias a que es muy entusiasta. Los quices son infinitos jaja, pero se puede sacar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'a8751b140dca26c1213be20c1af27ad001c03f57f11c25e46de4939543777d2f'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es muy buena profesora, muy ordenada y la mayoría de la materia la explica con claridad. Aveces recarga muchas las lecciones, y luego de una hora uno se esta durmiendo aunque sea muy didáctica. Practicas con un nivel similar a los exámenes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '3fb7c6baf9fae16d82de8016924f8233cfeebe60528c559052e717a41688c3c5'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Buena profesora, muy ordenada y clara en el momento de dar las lecciones en la parte virtual. Es una buena opción para meter el curso bimodal, pero el curso demanda invertir mucho tiempo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4e9519dfcbb92f37d9bf562124f8a45b05d7c15ae9b3eeeb4e359045ae646a55'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Muy buena profesora, explica claro. Los quices son fáciles. La modalidad semivirtual requiere mucho tiempo y dedicación, pero se aprende bastante.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'e309a691c991694f195710d8d207789b749ee163da88e56047e0fa30fb5acdc3'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Excelente profesora, la mejor para quimica 2'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'f3a74ba63d03e0fcb571efbc1341da1f798198d67116503c197342c75ead5ed5'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'El curso termina requiriendo más tiempo que uno en modalidad porque muchas veces lo hace llegar ambas lecciones, prácticas y por el portafolio que debe realizar cada semana. Si le sobra demasiadotiempo, llévelo. La profe es muy buena y hace muchos ejemplos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-16T00:00:00+00:00'::TIMESTAMPTZ, '496686304d46cda75cec7d4fda0657390bea7aa307e991a475bf905001127e96'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'La profe hace ejemplos con una dificultad mayor a la de los exámenes por lo que resulta más sencillo el examen. Explica lo importante en clases. La presentaciones y prácticas que envía sirven bastante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2018-12-04T00:00:00+00:00'::TIMESTAMPTZ, '4ab5446fb022def1958ceb8fa2e5e9d7dd567307be753b9e9299770d28666956'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Muy guapa y buena profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '3f781e13a2f82c8a5431e355df3ad02f00208ffd6e4067fcb2450998bc43a72d'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Una intensa y una profesora que da la clase como si los estudiantes tuvieran 3 anos.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'ed6ad78a7a5b16a766b828cddc437d5bbc44a75974cb1aa63452d5e7f9f676db'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Su clase es un poco aburrida. Se interesa por el aprendizaje del estudiante.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '50ea8a09ef3930e391b12337dbf764d188b8ebdb8077cd61f85cd5bd3eee5491'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Es una muy buena profe, explica súper bien y hace demasiados ejemplos. Si van a todas sus clases, de fijo van a pasar!! No es necesario matarse estudiando para que a uno le vaya bien en el examen porque la dificultad de los ejemplos de clase es mayor a la de los ejercicios del examen.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f486a74890badf03ae76ddcc04d3d4ba273dc3a91a21482035f65b5cd52bd1a3'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'De las mejores profesoras de la Escuela de Quimica, como profesora y como profesional. Hace que las clases no sean tan pesadas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, '59b1cb357bb1149f84a8fcc1631f047821d3efada22e415a45527d048b8f0763'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Buena profesora, es claro, muy ordenada en la parte virtual, una buena opción para meter el curso bimodal.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '271566a1b71793148e17dc59437310961ed275cc68e2b65fcf9220c1baed8d06'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Buena profe'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '78724e91ea68d0f55eb13e850ee09f0e90316f896f09fdefe85a7cc8c19959bb'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Es la mejor profesora de química II. Explica súper claro, deja los quices para la casa y uno que otro en clase. Hace demasiada práctica y es mucho más difícil la práctica que el examen. Demasiado recomendada, aunque es poco odiosa lo que importa es aprender y no tenerla de amiga.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '20c328970997885925a169f668f8e83d2ceb2d7ce60eb7ab3c236c9c86cce36e'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Buena profesora, se preocupa porque los estudiantes aprendan.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '8f284f75644ffb85ae9a07af27bb5bd45d3943def9789bd9a56e8dc7adb7f6fe'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Los exámenes son iguales a las prácticas de ella. Explica para tontos y es muy simpática. Hace consulta virtual donde explica lo que uno quiera con toda la calma del mundo. Perfecta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'a96ccaeb9d6c7fa304668bf47722556a5709b689514289693131113b0652c98c'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Lo mejor de la escuela de química. Explica súper claro, uno aprende bastante y el curso se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-02T00:00:00+00:00'::TIMESTAMPTZ, '640d3946e08950960a44f14c2227687ad08836cf907053ceff2183f279b1e161'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'De las mejores profesoras! Si tiene la oportunidad de matricular con ella ni lo piense. Muy buena gente y vacilona, se preocupa mucho por los alumnos. A veces hace quices durillos pero sirven mucho a la hora del examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '7984f4755bf3ac4dfbde75d11e93dc6138165eafb424a9ff21954761db61d989'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '7684191914bd74abce9390810170bea8cad5578dd2597094d449e1246311d705'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Si de verdad quiere apender, meta con ella, explica muy bien y deja muchos trabajos extra que le ayudan a uno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'c364d5640374bfac7ca71d76236fe660eb6ac96728ecc61b27942d20c740f61a'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Explica un poco rápido pero muy bien, deja bastantes tareas, cuices y trabajillos extra que le ayudan muchísimo a uno para pasar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '652c328fe6a80906200029250039eb9849c7eadeafa2200e4fd92c40f360dedf'::TEXT, ARRAY[573]::BIGINT[]),
    (555::BIGINT, 'De lo mejor de la escuela de química, tiene su cáracter, pero explica demasiado bien, repite cuantas veces sea necesario, hace muchos quices y actividades extra pero le ayudan un montón para prepararse como se debe para el examen, además que le ayuda a recuperar la nota de los quices bajos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'c1f2a85659b4da1da86e71f227f41d196f52b2c1b7190de8d2c668f2b2071832'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Explica demasiado bien, aunque es un poco grosera y parece que nada de mal humor. Deja demasiadas tareas extra pero son pequeñas, fáciles y la mayoría son opcionales para subir la nota de quiz presencial y da practicas demasiado utiles para el examen'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '2c4b5e791cb152574d5744bb69658e462db59cefefd075ac360ee1af7eb1de22'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '9ba78ee944e99eb2f2fd53866c0d52cf64c40e0e20d105df6b2c4d6051f28d6f'::TEXT, ARRAY[567, 613, 2738]::BIGINT[]),
    (555::BIGINT, 'Es una crack! Explica demasiado bien, si a uno no le queda claro, explica cuantas veces sea necesario. Hace muchas prácticas y quices, que a uno le ayudan demasiado para llegar seguro al examen. Es muy buena nota, eso sí, no llegue tarde ni use el cel en clase, si no...'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'bba7f996dfb3a544b2a4c7a72abd66bf5f38b98a1944997b7ff0c1f6a0ae16d9'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'En mi opinión es la mejor profe de laboratorio que hay... Si alguien es vago o mediocre de fijo pierde el curso, es BASTANTE exigente con los informes y la libreta pero uno aprende demasiado. Es muy buena persona y se empeña en que los estudiantes comprendan la materia. RECOMENDADÍSIMA. :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '80da30d6d0f3213ef2d384e2be045adc986e77869053e7271d28b8cd9c37b5a6'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6b691e4d9390d30cd13ab22e78a0cbbc3b5fe1814e47357f7609a06d23cae8de'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (555::BIGINT, 'Explica claro pero es muy exigente y califica muy duro. Te echa del laboratorio si ya es hora de salir'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '5048c13a0e588f8acb21182184f9c12904c5e9c6af8f11bcea1fe384cf09da2e'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (555::BIGINT, 'Hace muchos quices, explica muy bien, buena gente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'c6f7926e19b9f28b4c31c2f70211c9be99e487e822750b2d231f76233fe6b215'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Brinda apoyo a los estudiantes que lo necesitan principalmente'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2017-05-07T00:00:00+00:00'::TIMESTAMPTZ, '1cc8224fad14b594a2ce07e93643fae417baa7af002f4b4e25a557b9be0709f2'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (555::BIGINT, 'En lo que respecta a evaluación es bastante ruda. Hace muchos quices y explica muy bien, recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Muchos exámenes']::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, '08503ecf69d19d16c87b6af0773884d38ec45adb84497c4b13992b5c7a8b883c'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Súper recomendada. Explica muy bien.Hace muchos quices para eliminar los malos. Meta con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-01-21T00:00:00+00:00'::TIMESTAMPTZ, '565ffa1f29285d0878f1e8b1c8ccdbc2f778542ea45c27b902b038865ff86c26'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'explica todo lo del examen super bien, hay quices todas las semanas entonces se lleva la materia al dia. hace practica dificil muy buena igual a los que salen en el examen. es muy buena profe, se asegura de ver todos los temas bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-03T00:00:00+00:00'::TIMESTAMPTZ, '3102c7a97d43cdcd2807b5f6a780ab1d50800ada9cb6502894cc66f289ca9006'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (555::BIGINT, 'Se sale temprano si se puede,tambien adelanta la materia ,muchos quices de nivel de examen,lo que hace que te prepares bastante. Es muuyy puntual,llega antes para empezar a la hora que es. Es facil si se estudia y esta al dia ,sino ,se le viene la nota de los quices abajo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '693bc84718069156250bd1973da3fa0a037f6df8663bef631841ec961239bfb9'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Excelente profe. Explica todos los posibles ejercicios que puedan salir en el examen. Empieza la clase muy puntual'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'c0080ec401d0ce139c8bb098f45b095700e317c3f42625cfc5402feb1b21d40d'::TEXT, ARRAY[614]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '541b75a0b50cb6fb0d9b0e6b4a59d5d072919c18c10d662b6a5c57f0890a7e3f'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Explica todo muy claro, temperamental de vez en cuando la mayoría del tiempo es muy llevadera. 100% recomendada para Lab Q. 1.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f1f4ca26b5c2be107e726891c1a2b2f6935d49f8843f1099d699c80ba7255d3d'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (555::BIGINT, 'Es muy dura al calificar, comparando con otros profesores. Explica muy bien.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ee87af53c70141322832de549b6392a4873df562f1989fccd5028b661d3e3e3b'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6e9292234d0aab7cf28eedfd52445166ddbd1b52f111125dce3f61813ba433bc'::TEXT, ARRAY[573]::BIGINT[]),
    (555::BIGINT, 'Buena profe, accesible, pero un poquito mandona. La recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'd0042cb374fd6a17eaa021b6bb8cb6cdeb43f92d983c78d8f9197b3d7e352891'::TEXT, ARRAY[567]::BIGINT[]),
    (555::BIGINT, 'Buena profe, se aprende bastante. Muy recomendada. Y en cuanto a la evaluación es normal. Volvería a llevar con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, '1f86953d72a3c97b3d97e93a682dedea6ea03da7f1a8e4b601962f1ae0a4015e'::TEXT, ARRAY[567, 2738]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
